export type County = {
  name: string;
  slug: string;
  /** SVG path in a 0–1000 viewBox, generated by scripts/build_map.py */
  path: string;
  per100: number;
  deathsPooled: number;
  deathsPerYear: number;
  casesPerYearEst: number;
  pathwaysPerYearEst: number;
  ctPerWeekEst: number;
  lcMortality: number;
  copdPer100k: number;
  population: number;
  need: number | null;
  needRank: number | null;
  tooSmall: boolean;
  hasPrecedent: boolean;
};

export type National = {
  incidencePooled: number;
  mortalityPooled: number;
  incidenceMortalityRatio: number;
  dkRuledOutShare: number;
  pathwaysPerConfirmedCancer: number;
  chestXrayReported2024: number;
  thoraxCt2024: number;
  xrayToCtRatio: number;
  targetedAccessNationalAvg: number;
  swedenReferralToCtResultDays: number;
};

export type CountyData = {
  meta: Record<string, string>;
  national: National;
  counties: County[];
};

/** How far a number on screen can be trusted. Every figure carries one. */
export type Provenance = "sourced" | "estimate" | "unknown";
